class Solution:
    def averageHeightOfBuildings(self, buildings):
        pts = sorted({x for b in buildings for x in (b[0], b[1])})
        ans = []
        for i in range(len(pts) - 1):
            s, e = pts[i], pts[i + 1]
            total = cnt = 0
            for a, b, h in buildings:
                if a <= s and e <= b:
                    total += h
                    cnt += 1
            if cnt == 0:
                continue
            avg = total // cnt
            if ans and ans[-1][1] == s and ans[-1][2] == avg:
                ans[-1][1] = e
            else:
                ans.append([s, e, avg])
        return ans

