class Solution {
public:
    vector<vector<int>> averageHeightOfBuildings(vector<vector<int>>& buildings) {
        set<int> coords;
        for (auto& b : buildings) { coords.insert(b[0]); coords.insert(b[1]); }
        vector<int> pts(coords.begin(), coords.end());
        vector<vector<int>> ans;
        for (int i = 0; i + 1 < (int)pts.size(); i++) {
            long long total = 0;
            int cnt = 0;
            for (auto& b : buildings)
                if (b[0] <= pts[i] && pts[i + 1] <= b[1]) { total += b[2]; cnt++; }
            if (cnt == 0) continue;
            int avg = (int)(total / cnt);
            if (!ans.empty() && ans.back()[1] == pts[i] && ans.back()[2] == avg)
                ans.back()[1] = pts[i + 1];
            else
                ans.push_back({pts[i], pts[i + 1], avg});
        }
        return ans;
    }
};

