        for (int[] b : buildings) { cs.add(b[0]); cs.add(b[1]); }
        List<Integer> pts = new ArrayList<>(cs);
        List<int[]> ans = new ArrayList<>();
        for (int i = 0; i + 1 < pts.size(); i++) {
            long total = 0;
            int cnt = 0;
            for (int[] b : buildings)
                if (b[0] <= pts.get(i) && pts.get(i + 1) <= b[1]) { total += b[2]; cnt++; }
            if (cnt == 0) continue;
            int avg = (int)(total / cnt);
            if (!ans.isEmpty() && ans.get(ans.size() - 1)[1] == pts.get(i)
                               && ans.get(ans.size() - 1)[2] == avg)
                ans.get(ans.size() - 1)[1] = pts.get(i + 1);
            else
                ans.add(new int[]{pts.get(i), pts.get(i + 1), avg});
        }
        return ans.toArray(new int[0][]);
