from collections import defaultdict

class Solution:
    def averageHeightOfBuildings(self, buildings):
        delta = defaultdict(lambda: [0, 0])
        for s, e, h in buildings:
            delta[s][0] += h
            delta[s][1] += 1
            delta[e][0] -= h
            delta[e][1] -= 1
        ans = []
        total = cnt = prev = 0
        for p in sorted(delta):
            if cnt > 0:
                avg = total // cnt
                if ans and ans[-1][1] == prev and ans[-1][2] == avg:
                    ans[-1][1] = p
                else:
                    ans.append([prev, p, avg])
            total += delta[p][0]
            cnt += delta[p][1]
            prev = p
        return ans

