public:
    vector<vector<int>> averageHeightOfBuildings(vector<vector<int>>& buildings) {
        map<int, pair<long long, int>> delta;
        for (auto& b : buildings) {
            delta[b[0]].first += b[2];
            delta[b[0]].second += 1;
            delta[b[1]].first -= b[2];
            delta[b[1]].second -= 1;
        }
        vector<vector<int>> ans;
        long long total = 0;
        int cnt = 0, prev = 0;
        for (auto& [p, d] : delta) {
            if (cnt > 0) {
                int avg = (int)(total / cnt);
                if (!ans.empty() && ans.back()[1] == prev && ans.back()[2] == avg)
                    ans.back()[1] = p;
                else
                    ans.push_back({prev, p, avg});
            }
            total += d.first;
            cnt += d.second;
            prev = p;
        }
        return ans;
    }
};

