class Solution {
    public int[][] averageHeightOfBuildings(int[][] buildings) {
        TreeMap<Integer, long[]> delta = new TreeMap<>();
        for (int[] b : buildings) {
            delta.computeIfAbsent(b[0], k -> new long[2])[0] += b[2];
            delta.get(b[0])[1]++;
            delta.computeIfAbsent(b[1], k -> new long[2])[0] -= b[2];
            delta.get(b[1])[1]--;
        }
        List<int[]> res = new ArrayList<>();
        long total = 0, cnt = 0;
        int prev = 0;
        for (Map.Entry<Integer, long[]> e : delta.entrySet()) {
            int p = e.getKey();
            if (cnt > 0) {
                int avg = (int)(total / cnt);
                int[] last = res.isEmpty() ? null : res.get(res.size() - 1);
                if (last != null && last[1] == prev && last[2] == avg) last[1] = p;
                else res.add(new int[]{prev, p, avg});
            }
            total += e.getValue()[0];
            cnt += e.getValue()[1];
            prev = p;
        }
        return res.toArray(new int[0][]);
    }
}

