var averageHeightOfBuildings = function(buildings) {
    const delta = new Map();
    for (const [s, e, h] of buildings) {
        if (!delta.has(s)) delta.set(s, [0, 0]);
        if (!delta.has(e)) delta.set(e, [0, 0]);
        const a = delta.get(s), b = delta.get(e);
        a[0] += h; a[1]++;
        b[0] -= h; b[1]--;
    }
    const ans = [];
    let total = 0, cnt = 0, prev = 0;
    for (const p of [...delta.keys()].sort((x, y) => x - y)) {
        if (cnt > 0) {
            const avg = Math.floor(total / cnt);
            const last = ans[ans.length - 1];
            if (last && last[1] === prev && last[2] === avg) last[1] = p;
            else ans.push([prev, p, avg]);
        }
        const d = delta.get(p);
        total += d[0];
        cnt += d[1];
        prev = p;
    }
    return ans;
};
